function openSignin(){$("signin-status").textContent="";try{if(dlg.open)dlg.close();}catch(e){}try{signDlg.showModal();}catch(e){signDlg.setAttribute("open","");}$("signin-email").focus();}
function closeSignin(){try{signDlg.close();}catch(e){signDlg.removeAttribute("open");}}
$("signin-x").onclick=closeSignin;signDlg.addEventListener("click",e=>{if(e.target===signDlg)closeSignin();});
$("dlg-signin").onclick=openSignin;
$("dlg-join").onclick=()=>closeDlg();
(function(){const t=$("nav-toggle"),h=t.closest("header"),setOpen=o=>{h.classList.toggle("open",o);t.setAttribute("aria-expanded",o);t.setAttribute("aria-label",o?"Close menu":"Open menu");t.innerHTML=o?'<svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 6l12 12M18 6 6 18" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>':'<svg width="22" height="22" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 7h16M4 12h16M4 17h16" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg>';};t.onclick=()=>setOpen(!h.classList.contains("open"));$("nav-menu").addEventListener("click",e=>{if(e.target.closest("a"))setOpen(false);});document.addEventListener("keydown",e=>{if(e.key==="Escape")setOpen(false);});})();
/* Waiting lists: saved to Supabase (insert-only table) */
(function(){const d=$("wl-dlg"),COPY={"oracle-pro":{eb:"Oracle Pro",t:"Join the Oracle Pro waiting list",l:"You'll hear first when it opens, plus one honest update a month until then. No spam, ever.",c:"Email me about Oracle Pro and occasional updates from Jay's AI Playbook. I can unsubscribe whenever I like.",dt:"You're on the list, and you're early.",dx:"I'll email you once a month with honest progress, and you'll be first in when it opens. While you wait, your free 90-day plan is ready in the members area."},"playbooks":{eb:"Playbooks",t:"Tell me when the Playbooks are out",l:"Step-by-step guides for one job at a time. I'll email you when the first one's ready. No spam, ever.",c:"Email me when the Playbooks launch and with occasional updates from Jay's AI Playbook. I can unsubscribe whenever I like.",dt:"Lovely, you're on the list.",dx:"I'll email you the moment the first Playbook is ready. Until then, the free prompts and your 90-day plan are there whenever you want them."}};let list="oracle-pro";
  const open=l=>{list=COPY[l]?l:"oracle-pro";const c=COPY[list];$("wl-eyebrow").textContent=c.eb;$("wl-title").textContent=c.t;$("wl-lead").textContent=c.l;$("wl-consent-text").textContent=c.c;$("wl-done-title").textContent=c.dt;$("wl-done-text").textContent=c.dx;$("wl-ask").hidden=false;$("wl-done").hidden=true;$("wl-status").textContent="";try{const o=document.querySelector("dialog[open]");if(o&&o!==d)o.close();d.showModal();}catch(e){d.setAttribute("open","");}setTimeout(()=>$("wl-email").focus(),30);};
  const close=()=>{try{d.close();}catch(e){d.removeAttribute("open");}};
  document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("[data-waitlist]");if(!a)return;e.preventDefault();open(a.dataset.waitlist);});
  try{const j=new URLSearchParams(location.search).get("join");if(j&&COPY[j])setTimeout(()=>open(j),500);}catch(e){}
  $("wl-x").onclick=close;$("wl-close").onclick=close;d.addEventListener("click",e=>{if(e.target===d)close();});
  $("wl-form").addEventListener("submit",async e=>{e.preventDefault();const st=$("wl-status"),email=$("wl-email").value.trim().toLowerCase(),name=$("wl-name").value.trim();
    if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)){st.textContent="Please check your email address and try again.";return;}
    if(!$("wl-consent").checked){st.textContent="Please tick the box so I'm allowed to email you.";return;}
    $("wl-send").disabled=true;st.textContent="Adding you…";
    try{const r=await fetch(SB_BASE+"/rest/v1/waitlist",{method:"POST",headers:{apikey:SB_PUB,"Content-Type":"application/json",Prefer:"return=minimal"},body:JSON.stringify({email,first_name:name||null,list,source:(document.getElementById("jap-top")&&document.getElementById("jap-top").dataset.page)||JAP_PAGE||"home",consent:true,consent_text:$("wl-consent-text").textContent})});
      if(r.ok||r.status===409){$("wl-ask").hidden=true;$("wl-done").hidden=false;if(r.status===409)$("wl-done-title").textContent="Good news: you're already on the list.";}
      else throw new Error(r.status);}
    catch(err){st.textContent="That didn't go through. Please try again in a minute.";}
    finally{$("wl-send").disabled=false;}});
})();
$("lib-more").onclick=()=>{libLimit+=12;renderLib();};
document.addEventListener("click",e=>{const a=e.target.closest&&e.target.closest("a[href^='/']");if(!a||e.defaultPrevented||ON_SITE)return;
  const [path,hash]=a.getAttribute("href").split("#");const pg=JAP_PATHS[path];if(!pg)return;e.preventDefault();
  applyPage(pg);renderLib();renderVault();const t=hash&&document.getElementById(hash);if(t)t.scrollIntoView();else window.scrollTo(0,0);});
$("nav-signin").onclick=e=>{if(!/jaysaiplaybook\.blog$/.test(location.hostname)){e.preventDefault();if(memberState==="anon")openSignin();}};
function renderMemberBar(email){const bar=$("member-bar");bar.textContent="";
  if(memberState==="member"){bar.append("Signed in as "+email+" · Pro member. All Pro prompts are unlocked. ");}
  else if(memberState==="signed-in"){bar.append("Signed in as "+email+". Your account isn't on Pro yet, so Pro prompts stay locked. ");}
  else return;
  const out=document.createElement("button");out.type="button";out.className="linkish";out.textContent="Sign out";out.onclick=async()=>{try{await sb.auth.signOut();}catch(e){}location.reload();};bar.append(out);
  $("nav-signin").textContent=memberState==="anon"?"Members area":"My dashboard";}
async function loadProPreviews(){try{const r=await fetch(SB_BASE+"/rest/v1/premium_prompts?select=slug,title,industry,job,story,time_saved,tools,sort_order&published=eq.true&order=sort_order.asc",{headers:{apikey:SB_PUB}});if(!r.ok)return;const rows=await r.json();if(Array.isArray(rows)&&rows.length){PRO=rows.map(p=>Object.assign({pro:true},p));renderTiers();renderLib();}}catch(e){}}
async function refreshMember(){
  if(!sb)return;const {data}=await sb.auth.getSession();const sess=data&&data.session;
  if(!sess){memberState="anon";renderMemberBar();return;}
  const email=(sess.user&&sess.user.email)||"your account";
  const {data:rows,error}=await sb.from("premium_prompt_bodies").select("slug,prompt");
  if(!error&&rows&&rows.length){rows.forEach(r=>{PRO_BODIES[r.slug]=r.prompt;});memberState="member";}else{memberState="signed-in";}
  renderMemberBar(email);renderLib();
}
function loadSupabase(){return new Promise(res=>{if(window.supabase&&window.supabase.createClient)return res(true);const sc=document.createElement("script");sc.src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2.45.4/dist/umd/supabase.js";sc.onload=()=>res(!!(window.supabase&&window.supabase.createClient));sc.onerror=()=>res(false);document.head.appendChild(sc);});}
$("signin-form").addEventListener("submit",async e=>{e.preventDefault();const email=$("signin-email").value.trim();const st=$("signin-status");if(!email)return;
  if(!sb){st.textContent="Member sign-in works on jaysaiplaybook.blog. Please visit the site to sign in.";return;}
  $("signin-send").disabled=true;st.textContent="Sending…";
  const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:location.origin+location.pathname+"#prompts",shouldCreateUser:true}});
  $("signin-send").disabled=false;
  st.textContent=error?("That didn't go through: "+error.message+". Please try again in a minute."):"Check your inbox for a sign-in link from Jay's AI Playbook. It works once and expires after an hour.";});
loadProPreviews();
loadSupabase().then(ok=>{if(!ok)return;try{sb=window.supabase.createClient(SB_BASE,SB_PUB,{auth:{persistSession:true,detectSessionInUrl:true,flowType:"implicit"}});sb.auth.onAuthStateChange(()=>{refreshMember();});refreshMember();}catch(e){sb=null;}});
